import {cabinet,circle,text,ring,line,rand} from './cabinet.js';
export const angleGap=(a,b)=>Math.abs(Math.atan2(Math.sin(a-b),Math.cos(a-b)));
export function createOrbit(mount,api){const q=cabinet(mount,api,{accent:'#b9acff',height:440}),c=q.c;let angle=-Math.PI/2,target=.3,turn=1,life=3,hits=0,streak=0,flash=0;
 function hit(){if(!q.active)return;const width=Math.max(.16,.37-hits*.008),gap=angleGap(angle,target);if(gap<width){const perfect=gap<width*.32;streak++;hits++;q.add(perfect?20:10);q.sound(perfect?'perfect':'hit',Math.min(streak,8));q.burst(180+Math.cos(angle)*119,219+Math.sin(angle)*119);q.say(perfect?'PERFECT ORBIT · +20':'IN THE POCKET · +10');target=angle+turn*rand(1.5,4.5);if(hits%5===0){turn*=-1;target=angle+turn*rand(1.8,3.3);q.say('DIRECTION REVERSED');}flash=.22;}else{life--;streak=0;q.sound('miss');q.say('WAIT FOR THE LIT ARC');if(!life)q.finish('Out of orbit.',`${hits} targets caught. ${q.score} points.`);}}
 return {start(){angle=-Math.PI/2;target=.3;turn=1;life=3;hits=0;streak=0;flash=0;q.start();},tap:hit,action:hit,tick(dt){q.frame(dt,dt=>{angle+=turn*Math.min(3.3,1.5+hits*.045)*dt;flash=Math.max(0,flash-dt);if(q.elapsed>=45)q.finish('Perfectly in sync.',`${hits} targets in 45 seconds.`,true);},()=>{q.header(`${'♥ '.repeat(life).trim()}`,`${Math.max(0,Math.ceil(45-q.elapsed))}s`);const width=Math.max(.16,.37-hits*.008);for(let i=0;i<60;i++){const a=i*Math.PI/30;line(c,180+Math.cos(a)*139,219+Math.sin(a)*139,180+Math.cos(a)*(i%5?142:147),219+Math.sin(a)*(i%5?142:147),'#8794c044',1);}ring(c,180,219,119,'#334263',9);c.strokeStyle=flash?'#fff3cc':'#b9acff';c.lineWidth=16;c.beginPath();c.arc(180,219,119,target-width,target+width);c.stroke();for(let i=8;i>0;i--)circle(c,180+Math.cos(angle-turn*i*.065)*119,219+Math.sin(angle-turn*i*.065)*119,Math.max(1,7-i*.6),'#b9acff44');circle(c,180+Math.cos(angle)*119,219+Math.sin(angle)*119,10,'#f6f0ff');text(c,streak,180,209,54,'#e3dbff',700);text(c,'IN A ROW',180,248,14,'#a6b4ce');text(c,turn===1?'↻':'↺',180,295,25,'#b9acff');q.footer('Tap as the white dot enters the lit arc.');});},destroy:q.destroy};}
